<script setup lang="ts">
import {messageRef} from '../i18n/index.ts';
import {uiMessage,uiError,uiErrorMessage,localized} from '../modules/module-localization.ts';
import {tr} from '../i18n/index.ts';
import {ref,onMounted} from 'vue';
import FeedbackThread from './FeedbackThread.vue';
import {feedbackAuthor} from '../platform/feedback-profile.ts';
import {feedbackCall,type FeedbackIdentity} from '../platform/feedback.ts';
const props=defineProps<{accountLinked?:boolean}>();
const identity=ref<FeedbackIdentity>(),email=ref(''),code=ref(''),challenge=ref(''),busy=ref(false),error=messageRef(),note=messageRef(),retryAt=ref(0);
const health=ref<{mailConfigured:boolean;allowUnverified:boolean}>(),upgrading=ref(false);
async function status(){try{identity.value=await feedbackCall<FeedbackIdentity>('status');email.value=identity.value.email;health.value=await feedbackCall('health');}catch(exc){error.value=uiErrorMessage((exc as Error));}}
async function start(){busy.value=true;error.value='';try{if(health.value?.allowUnverified&&!health.value.mailConfigured){identity.value=await feedbackCall<FeedbackIdentity>('openDevice',{email:email.value});return;}const value=await feedbackCall<{challenge:string;retryAfter:number}>('verifyStart',{email:email.value});challenge.value=value.challenge;retryAt.value=Date.now()+value.retryAfter*1000;note.value=uiMessage('components.the_verification_code_is_scheduled_for_delivery_check_your');}catch(exc){error.value=uiErrorMessage((exc as Error));}finally{busy.value=false;}}
async function verify(){busy.value=true;error.value='';try{identity.value=await feedbackCall<FeedbackIdentity>('verifyFinish',{challenge:challenge.value,code:code.value});code.value='';upgrading.value=false;}catch(exc){error.value=uiErrorMessage((exc as Error));}finally{busy.value=false;}}
async function change(){try{identity.value=await feedbackCall<FeedbackIdentity>('resetIdentity');challenge.value='';note.value='';}catch(exc){error.value=uiErrorMessage((exc as Error));}}
onMounted(status);
</script>
<template>
<div class="feedback-panel" :class="{connected:identity?.connected&&!upgrading}">
  <template v-if="identity?.connected&&!upgrading"><div class="feedback-identity"><span>{{identity.email}} <small class="muted">{{identity.verified?tr('components.verified'):tr('components.contact_email_not_verified')}}</small></span><button v-if="identity.verified&&!accountLinked" @click="change">{{tr('components.change_email')}}</button><button v-else-if="!accountLinked&&health?.mailConfigured" @click="upgrading=true;error=''">{{tr('components.verify_contact_email')}}</button></div><FeedbackThread :owner="identity.owner"/></template>
  <section v-else-if="accountLinked" class="feedback-verification"><h3>{{tr('components.feedback')}}</h3><p class="muted">{{error||tr('components.connecting_to_this_account_s_feedback_conversation')}}</p><button v-if="error" @click="status">{{tr('components.retry_connection')}}</button></section>
  <form v-else class="feedback-verification" @submit.prevent="challenge?verify():start()"><div class="verification-author"><img :src="feedbackAuthor.avatar" :alt="feedbackAuthor.name+tr('components.s_avatar')"/><strong>{{feedbackAuthor.name}}</strong><span class="muted">{{tr('components.feedback')}}</span></div><h3>{{health?.allowUnverified&&!health.mailConfigured?tr('components.enter_a_contact_email_to_start_feedback'):tr('components.verify_your_email_for_your_first_message')}}</h3><p class="muted">{{tr('components.no_account_registration_or_password_is_needed_replies_are')}}</p><p v-if="health?.allowUnverified&&!health.mailConfigured" class="muted">{{tr('components.email_notifications_are_not_available_yet_jing_shaozi_may')}}</p><label>{{tr('components.email_address')}}<input v-model="email" type="email" autocomplete="email" required maxlength="254" :disabled="busy||!!challenge||upgrading" placeholder="name@example.com"/></label><template v-if="challenge"><label>{{tr('components.email_verification_code')}}<input v-model="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required :placeholder="tr('components.6_digit_code')"/></label><p class="muted" role="status">{{note}}</p></template><p v-if="error" class="feedback-error" role="alert">{{error}}</p><div class="verification-actions"><button class="primary" :disabled="busy||!health">{{busy?tr('components.processing'):challenge?tr('components.verify_and_open_conversation'):health?.allowUnverified&&!health.mailConfigured?tr('components.open_feedback_conversation'):tr('components.send_verification_code')}}</button><button v-if="upgrading" type="button" :disabled="busy" @click="upgrading=false;challenge='';code='';error=''">{{tr('components.return_to_conversation')}}</button><button v-if="!health" type="button" @click="status">{{tr('components.retry_connection')}}</button><button v-if="challenge&&!upgrading" type="button" :disabled="busy" @click="challenge='';code='';note=''">{{tr('components.use_another_email')}}</button><button v-if="challenge" type="button" :disabled="busy" @click="Date.now()>=retryAt?start():error=tr('components.wait_60_seconds_before_requesting_another_code')">{{tr('components.resend')}}</button></div><small>{{tr('components.the_server_stores_your_email_feedback_text_and_images')}}</small></form>
</div>
</template>
<style scoped>
.feedback-panel{display:flex;flex-direction:column;gap:16px;min-width:0}.feedback-panel.connected{height:min(65vh,680px);min-height:300px}.feedback-identity{display:flex;align-items:center;justify-content:space-between;gap:10px}.feedback-verification{width:100%;max-width:560px;margin:0 auto;display:flex;flex-direction:column;gap:18px}.feedback-verification h3{font-size:1.35rem;margin:6px 0 0}.feedback-verification p{margin:0;line-height:1.8}.feedback-verification>small{font-size:.8rem;line-height:1.75;color:var(--muted);border-top:1px solid var(--border);padding-top:16px}.feedback-verification input{min-height:42px}.verification-actions button{min-height:40px}.feedback-identity{font-size:.85rem;flex-wrap:wrap}.feedback-verification label{display:flex;flex-direction:column;gap:6px}.verification-actions{display:flex;gap:8px;flex-wrap:wrap}.feedback-error{color:var(--danger)}.verification-author{display:flex;align-items:center;gap:10px}.verification-author img{width:46px;height:46px;object-fit:cover;object-position:50% 32%;border-radius:50%;border:1px solid var(--border)}.verification-author span{font-size:.8rem}
</style>
